import net.nekocurit.i4399_ocr.I4399Ocr
import kotlin.io.encoding.Base64
import kotlin.test.Test
import kotlin.test.assertEquals

class OcrTest {
    @Test
    fun ocr() {
        val images = hashMapOf(
            "URHD" to "",
            "D6M2" to "",
            "QK2D" to ""
        )
            .forEach { (answer, image) ->
                assertEquals(I4399Ocr.ocr(Base64.decode(image)), answer)
            }
    }
}
